#[cfg(test)]
mod tests {
    use super::*;

    #[allow(clippy::many_single_char_names)] // r, g, b, h, s, n: the colour math's own names
    fn rgb(v: &serde_json::Value) -> Rgb {
        let s = v.as_str().expect("hex string");
        let n = u32::from_str_radix(s.trim_start_matches('#'), 16).expect("hex");
        let [_, r, g, b] = n.to_be_bytes();
        (r, g, b)
    }

    #[test]
    fn in_sync_with_theme_json() {
        let t: serde_json::Value =
            serde_json::from_str(include_str!("../../../../assets/theme.json"))
                .expect("theme.json");
        assert_eq!(ember::HI, rgb(&t["ember"]["hi"]), "run theme-gen");
        assert_eq!(ember::MID, rgb(&t["ember"]["mid"]), "run theme-gen");
        assert_eq!(ember::LO, rgb(&t["ember"]["lo"]), "run theme-gen");
        assert_eq!(ember::DEEP, rgb(&t["ember"]["deep"]), "run theme-gen");
        assert_eq!(ink::BG, rgb(&t["ink"]["bg"]), "run theme-gen");
        assert_eq!(ink::FACE_TOP, rgb(&t["ink"]["faceTop"]), "run theme-gen");
        assert_eq!(ink::FACE_LEFT, rgb(&t["ink"]["faceLeft"]), "run theme-gen");
        assert_eq!(
            ink::FACE_RIGHT,
            rgb(&t["ink"]["faceRight"]),
            "run theme-gen"
        );
        assert_eq!(ink::CREAM, rgb(&t["ink"]["cream"]), "run theme-gen");
        assert_eq!(
            status::SUCCESS,
            rgb(&t["status"]["success"]),
            "run theme-gen"
        );
        assert_eq!(
            status::WARNING,
            rgb(&t["status"]["warning"]),
            "run theme-gen"
        );
        assert_eq!(status::ERROR, rgb(&t["status"]["error"]), "run theme-gen");
        assert_eq!(status::INFO, rgb(&t["status"]["info"]), "run theme-gen");
        let g: Vec<Rgb> = t["gradient"]
            .as_array()
            .expect("gradient")
            .iter()
            .map(rgb)
            .collect();
        assert_eq!(GRADIENT.to_vec(), g, "run theme-gen");
        let ember_frames: Vec<&str> = t["frames"]["ember"]
            .as_array()
            .expect("frames")
            .iter()
            .filter_map(|v| v.as_str())
            .collect();
        assert_eq!(frames::EMBER.to_vec(), ember_frames, "run theme-gen");
    }
}
